mapper.select:
SELECT t.* FROM ( SELECT ps.*, s.name AS store_name, l.material_id, m.code AS material_code, m.name AS material_name, COALESCE(l.pack_qty, 1) AS pack_qty, CASE WHEN l.material_id IS NULL THEN NULL ELSE COALESCE((SELECT SUM(st.qty) FROM wms_stock st WHERE st.material_id = l.material_id AND st.warehouse_id = s.platform_warehouse_id), 0) / COALESCE(l.pack_qty, 1) END AS system_qty, CASE WHEN l.material_id IS NULL THEN NULL ELSE ps.fulfillable_qty - COALESCE((SELECT SUM(st.qty) FROM wms_stock st WHERE st.material_id = l.material_id AND st.warehouse_id = s.platform_warehouse_id), 0) / COALESCE(l.pack_qty, 1) END AS diff_qty FROM ecom_platform_stock ps JOIN ecom_store s ON s.id = ps.store_id LEFT JOIN ecom_listing l ON l.store_id = ps.store_id AND l.seller_sku = ps.seller_sku LEFT JOIN wms_material m ON m.id = l.material_id
ps.store_id = #{storeId}
AND (ps.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR ps.platform_item_id LIKE CONCAT('%', #{keyword}, '%') OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
) t
(t.diff_qty IS NULL OR t.diff_qty <> 0)
ORDER BY t.store_id, t.seller_sku
